1	package tracepath
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"sort"
9		"strings"
10		"time"
11		"unicode"
12	)
13	
14	const (
15		// idLayout is the timestamp format accepted on input and produced on output.
16		// It is time.RFC3339Nano trimmed of trailing zeros, so "…T00:00:00Z" stays
17		// readable while "…T00:00:00.000000001Z" keeps nanosecond precision.
18		idLayout = "2006-01-02T15:04:05.999999999Z07:00"
19	
20		maxIdentifierLength = 64
21		maxTextLength       = 128
22		maxAttributeCount   = 32
23		maxAttributeKey     = 64
24		maxAttributeValue   = 512
25		maxSpanCount        = 100000
26		maxBodyBytes        = 1 << 20
27	)
28	
29	// spanKinds is the closed set of span kinds.
30	var spanKinds = map[string]bool{
31		"internal": true,
32		"server":   true,
33		"client":   true,
34		"producer": true,
35		"consumer": true,
36	}
37	
38	// spanStatuses is the closed set of span statuses.
39	var spanStatuses = map[string]bool{"ok": true, "error": true}
40	
41	// SpanInput is one ingested span exactly as it arrived. The raw strings are
42	// kept verbatim so that persisted state round-trips byte for byte.
43	type SpanInput struct {
44		TraceID    string            `json:"trace_id"`
45		SpanID     string            `json:"span_id"`
46		ParentID   *string           `json:"parent_id"`
47		Service    string            `json:"service"`
48		Operation  string            `json:"operation"`
49		Kind       string            `json:"kind"`
50		StartTime  string            `json:"start_time"`
51		DurationNS int64             `json:"duration_ns"`
52		Status     string            `json:"status"`
53		Attributes map[string]string `json:"attributes"`
54		SpanCount  *int              `json:"span_count"`
55	}
56	
57	// IdempotencyRecord stores which resource the first request with a key created.
58	// The response body is re-rendered from state on every replay, so the recorded
59	// identity is enough to detect a key reused for a different operation.
60	type IdempotencyRecord struct {
61		Key       string `json:"key"`
62		Operation string `json:"operation"`
63		Identity  string `json:"identity"`
64		CreatedAt string `json:"created_at"`
65	}
66	
67	// Violation is one structural error found while assembling a trace.
68	type Violation struct {
69		Code    string `json:"code"`
70		TraceID string `json:"trace_id"`
71		SpanID  string `json:"span_id"`
72		Message string `json:"message"`
73	}
74	
75	// TraceNode is one span of the reassembled tree with its derived timing. The
76	// declared duration is never rewritten; timing violations are reported instead.
77	type TraceNode struct {
78		TraceID    string  `json:"trace_id"`
79		SpanID     string  `json:"span_id"`
80		ParentID   *string `json:"parent_id"`
81		Service    string  `json:"service"`
82		Operation  string  `json:"operation"`
83		Kind       string  `json:"kind"`
84		Status     string  `json:"status"`
85		StartTime  string  `json:"start_time"`
86		EndTime    string  `json:"end_time"`
87		DurationNS int64   `json:"duration_ns"`
88		SelfTimeNS int64   `json:"self_time_ns"`
89		// TotalDurationNS is the duration of the whole subtree of this span, derived
90		// from the declared values rather than from wall-clock arithmetic.
91		TotalDurationNS int64 `json:"subtree_duration_ns"`
92		// maxPath is the longest self_time-weighted path from this span downwards. It
93		// is internal bookkeeping and equals the span duration by construction.
94		maxPath      int64
95		Depth        int               `json:"depth"`
96		Error        bool              `json:"error"`
97		ErrorOrigin  bool              `json:"error_origin"`
98		Propagated   bool              `json:"propagated"`
99		ErrorOrigins []string          `json:"error_origins"`
100		Attributes   map[string]string `json:"attributes"`
101		Children     []*TraceNode      `json:"children"`
102	}
103	
104	// assignTiming derives self_time and the critical path of one subtree.
105	//
106	// LongestPath(t) is the largest sum of self_time on any path from t downwards.
107	// The critical branch K is the child with the largest LongestPath. self_time(t)
108	// is then everything of t's duration that K does not account for:
109	// duration(t) - LongestPath(K), where a leaf is its own critical branch. That
110	// makes self_time exactly the exclusive time off the critical path, so the self
111	// times along the critical path add up to duration(t), which is the invariant
112	// this service promises.
113	//
114	// Children are independent of each other, so LongestPath(child) can be computed
115	// before self_time(t) and does not change afterwards.
116	func assignTiming(node *TraceNode) {
117		if len(node.Children) == 0 {
118			node.SelfTimeNS = node.DurationNS
119			node.maxPath = node.DurationNS
120			return
121		}
122		critical := node.Children[0]
123		for _, child := range node.Children {
124			assignTiming(child)
125			if child.maxPath > critical.maxPath {
126				critical = child
127			}
128		}
129		selfTime := node.DurationNS - critical.maxPath
130		if selfTime < 0 {
131			selfTime = 0
132		}
133		node.SelfTimeNS = selfTime
134		node.maxPath = selfTime + critical.maxPath
135		if node.maxPath > node.DurationNS {
136			node.maxPath = node.DurationNS
137		}
138	}
139	
140	// Trace is a fully reassembled trace. Valid is false when Violations is not
141	// empty; the tree is still returned so a caller can inspect the damage.
142	type Trace struct {
143		TraceID       string       `json:"trace_id"`
144		Root          *TraceNode   `json:"root"`
145		DurationNS    int64        `json:"duration_ns"`
146		SpanCount     int          `json:"span_count"`
147		ServiceCount  int          `json:"service_count"`
148		ErrorSpans    int          `json:"error_spans"`
149		RootSpanCount int          `json:"declared_span_count"`
150		Complete      bool         `json:"complete"`
151		Valid         bool         `json:"valid"`
152		Violations    []Violation  `json:"violations"`
153		Spans         []*TraceNode `json:"spans"`
154	}
155	
156	// PathStep is one hop of the critical path.
157	type PathStep struct {
158		SpanID     string  `json:"span_id"`
159		ParentID   *string `json:"parent_id"`
160		Service    string  `json:"service"`
161		Operation  string  `json:"operation"`
162		Depth      int     `json:"depth"`
163		SelfTimeNS int64   `json:"self_time_ns"`
164		StartTime  string  `json:"start_time"`
165		EndTime    string  `json:"end_time"`
166	}
167	
168	// CriticalPath is the weighted longest path through the span tree.
169	type CriticalPath struct {
170		TraceID         string       `json:"trace_id"`
171		Method          string       `json:"method"`
172		TraceDurationNS int64        `json:"trace_duration_ns"`
173		Path            []PathStep   `json:"path"`
174		LengthNS        int64        `json:"length_ns"`
175		Complete        bool         `json:"complete"`
176		Valid           bool         `json:"valid"`
177		Violations      []Validation `json:"violations"`
178	}
179	
180	// OperationStat aggregates one (service, operation) pair.
181	type OperationStat struct {
182		Operation      string `json:"operation"`
183		SpanCount      int    `json:"span_count"`
184		ErrorSpans     int    `json:"error_spans"`
185		SelfTimeNS     int64  `json:"self_time_ns"`
186		MinDurationNS  int64  `json:"min_duration_ns"`
187		MaxDurationNS  int64  `json:"max_duration_ns"`
188		MeanDurationNS int64  `json:"mean_duration_ns"`
189		P50DurationNS  int64  `json:"p50_duration_ns"`
190		P95DurationNS  int64  `json:"p95_duration_ns"`
191		durations      []int64
192	}
193	
194	// ServiceStat aggregates one service.
195	type ServiceStat struct {
196		Service        string           `json:"service"`
197		SpanCount      int              `json:"span_count"`
198		ErrorSpans     int              `json:"error_spans"`
199		RootSpans      int              `json:"root_spans"`
200		SelfTimeNS     int64            `json:"self_time_ns"`
201		MinDurationNS  int64            `json:"min_duration_ns"`
202		MaxDurationNS  int64            `json:"max_duration_ns"`
203		MeanDurationNS int64            `json:"mean_duration_ns"`
204		P50DurationNS  int64            `json:"p50_duration_ns"`
205		P95DurationNS  int64            `json:"p95_duration_ns"`
206		Operations     []*OperationStat `json:"operations"`
207		durations      []int64
208	}
209	
210	// ServiceEdge aggregates one caller/callee pair.
211	type ServiceEdge struct {
212		Caller         string `json:"caller"`
213		Callee         string `json:"callee"`
214		CallCount      int    `json:"call_count"`
215		ErrorCount     int    `json:"error_count"`
216		MinDurationNS  int64  `json:"min_duration_ns"`
217		MaxDurationNS  int64  `json:"max_duration_ns"`
218		MeanDurationNS int64  `json:"mean_duration_ns"`
219		P50DurationNS  int64  `json:"p50_duration_ns"`
220		P95DurationNS  int64  `json:"p95_duration_ns"`
221		durations      []int64
222	}
223	
224	// GraphStats is the process-wide roll-up that accompanies the service graph.
225	type GraphStats struct {
226		TraceCount     int   `json:"trace_count"`
227		SpanCount      int   `json:"span_count"`
228		ErrorSpans     int   `json:"error_spans"`
229		DurationNS     int64 `json:"duration_ns"`
230		MeanDurationNS int64 `json:"mean_duration_ns"`
231		P50DurationNS  int64 `json:"p50_duration_ns"`
232		P95DurationNS  int64 `json:"p95_duration_ns"`
233		PartialTraces  int   `json:"partial_traces"`
234		durations      []int64
235	}
236	
237	// ServiceGraph is the aggregated service dependency graph.
238	type ServiceGraph struct {
239		TraceID  *string        `json:"trace_id"`
240		Services []*ServiceStat `json:"services"`
241		Edges    []*ServiceEdge `json:"edges"`
242		Stats    *GraphStats    `json:"stats"`
243	}
244	
245	// TraceSummary is one entry of GET /traces.
246	type TraceSummary struct {
247		TraceID      string  `json:"trace_id"`
248		RootSpanID   *string `json:"root_span_id"`
249		RootService  *string `json:"root_service"`
250		StartTime    string  `json:"start_time"`
251		DurationNS   int64   `json:"duration_ns"`
252		SpanCount    int     `json:"span_count"`
253		ServiceCount int     `json:"service_count"`
254		ErrorSpans   int     `json:"error_spans"`
255		Complete     bool    `json:"complete"`
256		Valid        bool    `json:"valid"`
257		// rootInstant is the parsed root start time used by the list ordering and by
258		// the start_from/start_to filters. It is not part of the JSON contract.
259		rootInstant time.Time
260	}
261	
262	// decodeObject strictly decodes one JSON object. Unknown fields, trailing
263	// content and non-object bodies are all rejected.
264	func decodeObject(body []byte, target any) error {
265		if len(bytes.TrimSpace(body)) == 0 {
266			return ValidationError("request body must be a JSON object")
267		}
268		decoder := json.NewDecoder(bytes.NewReader(body))
269		decoder.DisallowUnknownFields()
270		if err := decoder.Decode(target); err != nil {
271			return ValidationError("request body must be a JSON object with known fields: %s", err)
272		}
273		if err := decoder.Decode(new(any)); err != io.EOF {
274			return ValidationError("request body must contain exactly one JSON object")
275		}
276		return nil
277	}
278	
279	// formatTime renders one UTC instant in the canonical layout.
280	func formatTime(instant time.Time) string {
281		return instant.UTC().Format(idLayout)
282	}
283	
284	// parseTime accepts an RFC3339 timestamp with optional fractional seconds.
285	func parseTime(value string, field string) (time.Time, error) {
286		if strings.TrimSpace(value) == "" {
287			return time.Time{}, ValidationError("%s is required", field)
288		}
289		instant, err := time.Parse(time.RFC3339Nano, value)
290		if err != nil {
291			return time.Time{}, ValidationError("%s must be an RFC3339 timestamp", field)
292		}
293		return instant.UTC(), nil
294	}
295	
296	// containsFold reports whether text contains needle under Unicode simple case
297	// folding, the substring analogue of strings.EqualFold. Runes are compared by
298	// walking the complete SimpleFold equivalence cycle, the same rule
299	// strings.EqualFold applies at one rune position.
300	func containsFold(text string, needle string) bool {
301		if needle == "" {
302			return true
303		}
304		haystack := []rune(text)
305		target := []rune(needle)
306		if len(target) > len(haystack) {
307			return false
308		}
309		for start := 0; start <= len(haystack)-len(target); start++ {
310			matches := true
311			for offset := range target {
312				if !runesEqualFold(haystack[start+offset], target[offset]) {
313					matches = false
314					break
315				}
316			}
317			if matches {
318				return true
319			}
320		}
321		return false
322	}
323	
324	// runesEqualFold reports whether two runes are simple-case-fold equivalent.
325	func runesEqualFold(left rune, right rune) bool {
326		if left == right {
327			return true
328		}
329		for r := unicode.SimpleFold(left); r != left; r = unicode.SimpleFold(r) {
330			if r == right {
331				return true
332			}
333		}
334		return false
335	}
336	
337	func validateIdentifier(value string, field string) (string, error) {
338		trimmed := strings.TrimSpace(value)
339		if trimmed == "" {
340			return "", ValidationError("%s is required", field)
341		}
342		if len(trimmed) > maxIdentifierLength {
343			return "", ValidationError("%s must be at most %d characters", field, maxIdentifierLength)
344		}
345		return trimmed, nil
346	}
347	
348	func validateText(value string, field string) (string, error) {
349		trimmed := strings.TrimSpace(value)
350		if trimmed == "" {
351			return "", ValidationError("%s is required", field)
352		}
353		if len(trimmed) > maxTextLength {
354			return "", ValidationError("%s must be at most %d characters", field, maxTextLength)
355		}
356		return trimmed, nil
357	}
358	
359	// validateSpanInput checks every rule that can be decided without looking at
360	// the other spans of the trace.
361	func validateSpanInput(input *SpanInput) (time.Time, error) {
362		if _, err := validateIdentifier(input.TraceID, "trace_id"); err != nil {
363			return time.Time{}, err
364		}
365		if _, err := validateIdentifier(input.SpanID, "span_id"); err != nil {
366			return time.Time{}, err
367		}
368		if input.ParentID != nil {
369			if strings.TrimSpace(*input.ParentID) == "" {
370				return time.Time{}, ValidationError("parent_id must be null or a non-empty identifier")
371			}
372		}
373		if _, err := validateText(input.Service, "service"); err != nil {
374			return time.Time{}, err
375		}
376		if _, err := validateText(input.Operation, "operation"); err != nil {
377			return time.Time{}, err
378		}
379		if !spanKinds[input.Kind] {
380			return time.Time{}, ValidationError("kind must be one of internal, server, client, producer or consumer")
381		}
382		if !spanStatuses[input.Status] {
383			return time.Time{}, ValidationError("status must be ok or error")
384		}
385		start, err := parseTime(input.StartTime, "start_time")
386		if err != nil {
387			return time.Time{}, err
388		}
389		if input.DurationNS < 0 {
390			return time.Time{}, ValidationError("duration_ns must be zero or positive")
391		}
392		if int64(start.UnixNano())+input.DurationNS > int64(maxTime.UnixNano()) {
393			return time.Time{}, ValidationError("start_time + duration_ns is beyond the supported range")
394		}
395		if len(input.Attributes) > maxAttributeCount {
396			return time.Time{}, ValidationError("attributes must contain at most %d entries", maxAttributeCount)
397		}
398		keys := make([]string, 0, len(input.Attributes))
399		for key := range input.Attributes {
400			keys = append(keys, key)
401		}
402		sort.Strings(keys)
403		for _, key := range keys {
404			if key == "" {
405				return time.Time{}, ValidationError("attribute keys must not be empty")
406			}
407			if len(key) > maxAttributeKey {
408				return time.Time{}, ValidationError("attribute key %s must be at most %d characters", key, maxAttributeKey)
409			}
410			if len(input.Attributes[key]) > maxAttributeValue {
411				return time.Time{}, ValidationError("attribute %s must be at most %d characters", key, maxAttributeValue)
412			}
413		}
414		if input.ParentID != nil && *input.ParentID == input.SpanID {
415			return time.Time{}, ValidationError("parent_id must not equal span_id on span %s", input.SpanID)
416		}
417		if input.ParentID == nil {
418			if input.SpanCount == nil {
419				return time.Time{}, ValidationError("span_count is required on a root span (parent_id null)")
420			}
421			if *input.SpanCount < 1 {
422				return time.Time{}, ValidationError("span_count must be at least 1")
423			}
424			if *input.SpanCount > maxSpanCount {
425				return time.Time{}, ValidationError("span_count must be at most %d", maxSpanCount)
426			}
427		} else if input.SpanCount != nil {
428			return time.Time{}, ValidationError("span_count is only allowed on a root span")
429		}
430		return start, nil
431	}
432	
433	// maxTime bounds start_time + duration_ns so that UnixNano arithmetic cannot
434	// overflow int64.
435	var maxTime = time.Date(2262, 4, 11, 23, 47, 16, 0, time.UTC)
436	
437	// lineOf resolves a span's trace id by walking parent links, which also detects
438	// a parent cycle and a parent that lives in another trace. A parent that has
439	// not been ingested yet simply ends the walk: every span of a trace carries the
440	// same trace id, so the input's own id is the answer.
441	func lineOf(spans map[string]*SpanInput, input *SpanInput) (string, error) {
442		seen := map[string]bool{input.SpanID: true}
443		current := input
444		for current.ParentID != nil {
445			parentID := *current.ParentID
446			if seen[parentID] {
447				return "", ConflictError("span %s has a cyclic parent_id chain", input.SpanID)
448			}
449			parent, found := spans[parentID]
450			if !found {
451				return input.TraceID, nil
452			}
453			seen[parentID] = true
454			if parent.TraceID != input.TraceID {
455				return "", ConflictError("span %s belongs to trace %s but its parent %s belongs to trace %s",
456					input.SpanID, input.TraceID, parentID, parent.TraceID)
457			}
458			current = parent
459		}
460		return input.TraceID, nil
461	}
462	
463	type treeBuilder struct {
464		spans      map[string]*SpanInput
465		children   map[string][]*SpanInput
466		roots      []*SpanInput
467		violations []Violation
468	}
469	
470	// assembleTrace rebuilds the span tree of one trace and derives every timing
471	// value. Violations are collected, never fatal, so a caller always sees why a
472	// trace is unusable.
473	func assembleTrace(traceID string, spans map[string]*SpanInput) *Trace {
474		trace := &Trace{
475			TraceID:    traceID,
476			SpanCount:  len(spans),
477			Valid:      true,
478			Violations: []Violation{},
479			Spans:      []*TraceNode{},
480		}
481		builder := &treeBuilder{
482			spans:    spans,
483			children: map[string][]*SpanInput{},
484		}
485		ids := make([]string, 0, len(spans))
486		for id := range spans {
487			ids = append(ids, id)
488		}
489		sort.Strings(ids)
490		for _, id := range ids {
491			span := spans[id]
492			if span.ParentID == nil {
493				builder.roots = append(builder.roots, span)
494				continue
495			}
496			if _, found := spans[*span.ParentID]; !found {
497				builder.violations = append(builder.violations, Violation{
498					Code:    "orphan_span",
499					TraceID: traceID,
500					SpanID:  span.SpanID,
501					Message: fmt.Sprintf("span %s references parent %s which is not part of trace %s",
502						span.SpanID, *span.ParentID, traceID),
503				})
504				continue
505			}
506			builder.children[*span.ParentID] = append(builder.children[*span.ParentID], span)
507		}
508		declared := 0
509		if len(builder.roots) == 1 && builder.roots[0].SpanCount != nil {
510			declared = *builder.roots[0].SpanCount
511		}
512		switch {
513		case len(builder.roots) == 1:
514		case len(builder.roots) == 0:
515			builder.violations = append(builder.violations, Violation{
516				Code:    "no_root_span",
517				TraceID: traceID,
518				SpanID:  "",
519				Message: fmt.Sprintf("trace %s has no span with a null parent_id", traceID),
520			})
521		default:
522			names := make([]string, 0, len(builder.roots))
523			for _, root := range builder.roots {
524				names = append(names, root.SpanID)
525			}
526			sort.Strings(names)
527			builder.violations = append(builder.violations, Violation{
528				Code:    "multiple_root_spans",
529				TraceID: traceID,
530				SpanID:  names[0],
531				Message: fmt.Sprintf("trace %s has %d root spans: %s", traceID, len(names), strings.Join(names, ", ")),
532			})
533		}
534		trace.RootSpanCount = declared
535		trace.Complete = len(builder.roots) == 1 && declared != 0 && declared == len(spans)
536		if declared != 0 && declared < len(spans) {
537			builder.violations = append(builder.violations, Violation{
538				Code:    "span_count_exceeded",
539				TraceID: traceID,
540				SpanID:  builder.roots[0].SpanID,
541				Message: fmt.Sprintf("trace %s declared span_count %d but %d spans were ingested",
542					traceID, declared, len(spans)),
543			})
544		}
545		if declared != 0 && declared > len(spans) {
546			builder.violations = append(builder.violations, Violation{
547				Code:    "trace_incomplete",
548				TraceID: traceID,
549				SpanID:  builder.roots[0].SpanID,
550				Message: fmt.Sprintf("trace %s declared span_count %d but only %d spans were ingested",
551					traceID, declared, len(spans)),
552			})
553		}
554	
555		// Every span that has no reachable root is still reported, as its own tree.
556		reachable := map[string]bool{}
557		for _, root := range builder.roots {
558			builder.markReachable(root, reachable)
559		}
560		for _, id := range ids {
561			if !reachable[id] && !builder.isOrphan(id) {
562				builder.violations = append(builder.violations, Violation{
563					Code:    "unreachable_span",
564					TraceID: traceID,
565					SpanID:  id,
566					Message: fmt.Sprintf("span %s is not reachable from a root span", id),
567				})
568			}
569		}
570	
571		sortedRoots := append([]*SpanInput{}, builder.roots...)
572		sort.Slice(sortedRoots, func(i, j int) bool {
573			left, _ := parseTime(sortedRoots[i].StartTime, "start_time")
574			right, _ := parseTime(sortedRoots[j].StartTime, "start_time")
575			if !left.Equal(right) {
576				return left.Before(right)
577			}
578			return sortedRoots[i].SpanID < sortedRoots[j].SpanID
579		})
580		for _, root := range sortedRoots {
581			start, _ := parseTime(root.StartTime, "start_time")
582			node := builder.buildNode(root, start, 0)
583			assignTiming(node)
584			trace.Spans = append(trace.Spans, flatten(node)...)
585			if trace.Root == nil {
586				trace.Root = node
587				trace.DurationNS = node.DurationNS
588			}
589		}
590		services := map[string]bool{}
591		for _, node := range trace.Spans {
592			collectServices(node, services)
593		}
594		trace.ServiceCount = len(services)
595		trace.ErrorSpans = countErrorSpans(trace.Spans)
596		trace.Valid = len(builder.violations) == 0
597		trace.Violations = builder.violations
598		sortViolations(trace.Violations)
599		return trace
600	}
601	
602	func (b *treeBuilder) isOrphan(id string) bool {
603		span := b.spans[id]
604		return span.ParentID != nil && b.spans[*span.ParentID] == nil
605	}
606	
607	func (b *treeBuilder) markReachable(span *SpanInput, seen map[string]bool) {
608		if seen[span.SpanID] {
609			return
610		}
611		seen[span.SpanID] = true
612		for _, child := range b.children[span.SpanID] {
613			b.markReachable(child, seen)
614		}
615	}
616	
617	// buildNode derives one node and everything below it. parentEnd is the
618	// exclusive end instant of the enclosing span; a child that overruns it is
619	// recorded as a violation and the node is still returned.
620	func (b *treeBuilder) buildNode(span *SpanInput, parentEnd time.Time, depth int) *TraceNode {
621		start, err := parseTime(span.StartTime, "start_time")
622		if err != nil {
623			start = time.Time{}
624		}
625		end := start.Add(time.Duration(span.DurationNS))
626		node := &TraceNode{
627			TraceID:      span.TraceID,
628			SpanID:       span.SpanID,
629			ParentID:     span.ParentID,
630			Service:      span.Service,
631			Operation:    span.Operation,
632			Kind:         span.Kind,
633			Status:       span.Status,
634			StartTime:    span.StartTime,
635			EndTime:      formatTime(end),
636			DurationNS:   span.DurationNS,
637			Depth:        depth,
638			Error:        span.Status == "error",
639			Attributes:   map[string]string{},
640			Children:     []*TraceNode{},
641			ErrorOrigins: []string{},
642		}
643		for key, value := range span.Attributes {
644			node.Attributes[key] = value
645		}
646		children := append([]*SpanInput{}, b.children[span.SpanID]...)
647		sort.Slice(children, func(i, j int) bool {
648			left, _ := parseTime(children[i].StartTime, "start_time")
649			right, _ := parseTime(children[j].StartTime, "start_time")
650			if !left.Equal(right) {
651				return left.Before(right)
652			}
653			return children[i].SpanID < children[j].SpanID
654		})
655		previousEnd := start
656		previousID := ""
657		for _, child := range children {
658			childStart, _ := parseTime(child.StartTime, "start_time")
659			childEnd := childStart.Add(time.Duration(child.DurationNS))
660			if childStart.Before(start) || childEnd.After(end) {
661				b.violations = append(b.violations, Violation{
662					Code:    "time_not_contained",
663					TraceID: span.TraceID,
664					SpanID:  child.SpanID,
665					Message: fmt.Sprintf("span %s runs from %s to %s which is not contained in parent %s from %s to %s",
666						child.SpanID, child.StartTime, formatTime(childEnd), span.SpanID, span.StartTime, formatTime(end)),
667				})
668			}
669			// Siblings must not overlap. Comparing each child against the furthest end
670			// seen so far catches an overlap with any earlier sibling, not only with
671			// the neighbour that starts just before it.
672			if previousID != "" && childStart.Before(previousEnd) {
673				b.violations = append(b.violations, Violation{
674					Code:    "sibling_overlap",
675					TraceID: span.TraceID,
676					SpanID:  previousID,
677					Message: fmt.Sprintf("span %s starts at %s before sibling %s ends at %s inside parent %s",
678						child.SpanID, child.StartTime, previousID, formatTime(previousEnd), span.SpanID),
679				})
680			}
681			if childEnd.After(previousEnd) {
682				previousEnd = childEnd
683				previousID = child.SpanID
684			}
685			node.Children = append(node.Children, b.buildNode(child, end, depth+1))
686		}
687		node.TotalDurationNS = span.DurationNS
688		for _, child := range node.Children {
689			if child.TotalDurationNS > span.DurationNS {
690				b.violations = append(b.violations, Violation{
691					Code:    "time_not_contained",
692					TraceID: span.TraceID,
693					SpanID:  child.SpanID,
694					Message: fmt.Sprintf("subtree of %s lasts %d but its parent %s only lasts %d",
695						child.SpanID, child.TotalDurationNS, span.SpanID, span.DurationNS),
696				})
697			}
698			if child.TotalDurationNS > node.TotalDurationNS {
699				node.TotalDurationNS = child.TotalDurationNS
700			}
701		}
702		origins := map[string]bool{}
703		if node.Error {
704			origins[span.SpanID] = true
705		}
706		for _, child := range node.Children {
707			for _, origin := range child.ErrorOrigins {
708				origins[origin] = true
709			}
710		}
711		for origin := range origins {
712			node.ErrorOrigins = append(node.ErrorOrigins, origin)
713		}
714		sort.Strings(node.ErrorOrigins)
715		node.ErrorOrigin = node.Error
716		// propagated marks a span whose subtree contains a failure that did not
717		// happen on the span itself. The declared status stays untouched: only the
718		// failing origin carries status "error".
719		node.Propagated = false
720		for _, origin := range node.ErrorOrigins {
721			if origin != node.SpanID {
722				node.Propagated = true
723				break
724			}
725		}
726		return node
727	}
728	
729	func collectServices(node *TraceNode, into map[string]bool) {
730		if into[node.Service] {
731			return
732		}
733		into[node.Service] = true
734		for _, child := range node.Children {
735			collectServices(child, into)
736		}
737	}
738	
739	// countErrorSpans counts failed spans in a flat span list. The list already
740	// contains every node once, so the nodes themselves are never walked again.
741	func countErrorSpans(nodes []*TraceNode) int {
742		total := 0
743		for _, node := range nodes {
744			if node.Error {
745				total++
746			}
747		}
748		return total
749	}
750	
751	func sortViolations(violations []Violation) {
752		sort.Slice(violations, func(i, j int) bool {
753			if violations[i].SpanID != violations[j].SpanID {
754				return violations[i].SpanID < violations[j].SpanID
755			}
756			return violations[i].Code < violations[j].Code
757		})
758	}
759	
760	// flatten walks the tree in pre-order and returns the nodes it contains.
761	func flatten(root *TraceNode) []*TraceNode {
762		if root == nil {
763			return nil
764		}
765		nodes := []*TraceNode{root}
766		for _, child := range root.Children {
767			nodes = append(nodes, flatten(child)...)
768		}
769		return nodes
770	}
