func (s *Service) IngestSpanBatch(body []byte, key string) (any, error) {
    if err := validateIdempotencyKey(key); err != nil { return nil, err }
    var envelope struct {
        Spans []json.RawMessage `json:"spans"`
    }
    if err := decodeObject(body, &envelope); err != nil { return nil, err }
    if len(envelope.Spans) == 0 { return nil, ValidationError("spans must contain at least 1 span") }
    if len(envelope.Spans) > maxBatchSpans { return nil, ValidationError("spans must contain at most %d spans", maxBatchSpans) }

    identity := hash of body
    var response any
    err := s.store.Update(func(state *State) error {
        if record, found := state.Idempotency[key]; found {
            if record.Operation != operation { return ConflictError("idempotency key was already used for another operation") }
            if record.Identity != identity { return ConflictError("idempotency key was already used for a different batch") }
            response = record.Response  // json.RawMessage
            return nil
        }
        items := make([]*batchAccepted, 0, len(envelope.Spans))
        for index, raw := range envelope.Spans {
            input, start, spanID, traceID, err := decodeAndValidateSpan(raw)
            if err != nil { return err }
            if err := applySpan(state, input, start, spanID, traceID); err != nil { return err }
            items = append(items, acceptedItem(state, traceID, spanID))
        }
        result := &batchResponse{Accepted: items, Count: len(items)}
        encoded, err := json.Marshal(result)
        if err != nil { return InternalError(...) }
        state.Idempotency[key] = &IdempotencyRecord{Key: key, Operation: operation, Identity: identity, CreatedAt: s.now(), Response: encoded}
        response = result
        return nil
    })
    if err != nil { return nil, err }
    return response, nil
}
```

